-- User authentication

CREATE TABLE IF NOT EXISTS `User` (
    pid VARCHAR(16) NOT NULL UNIQUE,
    permissions INT(11) NOT NULL DEFAULT 0,
    campus INT(11) NOT NULL DEFAULT 2
);

