    ('jaden03', '1', '2');

CREATE TABLE IF NOT EXISTS `Log` (
    pid VARCHAR(16) DEFAULT "SYSTEM" NOT NULL,
    action TEXT NOT NULL,
    timestamp TIMESTAMP NOT NULL DEFAULT NOW(),
    severity ENUM('info', 'warning', 'error') NOT NULL DEFAULT 'info'
);

CREATE TABLE IF NOT EXISTS `Submission_Info` (
    initiating_user_pid VARCHAR(16),
    timestamp TIMESTAMP NOT NULL DEFAULT NOW(),
    filename TEXT NOT NULL,
    processing_time_ms INT NOT NULL,
    num_students INT NOT NULL,
    num_flagged_students INT NOT NULL
);

-- PTD

CREATE TABLE IF NOT EXISTS `Audit_Info`(
    audit_id INT PRIMARY KEY NOT NULL AUTO_INCREMENT,
    initiating_user_pid VARCHAR(16),
    timestamp TIMESTAMP NOT NULL DEFAULT NOW(),
    filename TEXT NOT NULL,
    processing_time_ms INT NOT NULL,
    num_students INT NOT NULL,
    num_incomplete_degree_students INT NOT NULL
);

CREATE TABLE IF NOT EXISTS `Student_Progress`(
    id INT NOT NULL,
    name VARCHAR(128) NOT NULL,
    standing_message VARCHAR(64) NOT NULL,
    admit_term INT NOT NULL,
    current_term INT NOT NULL,
    concentration VARCHAR(3) DEFAULT "CS" NOT NULL,
    advisor_lname VARCHAR(64) NOT NULL,
    overall_hours_attempted INT NOT NULL,
    overall_gpa FLOAT NOT NULL,
    transfer_hours_earned INT NOT NULL,
    in_major_gpa FLOAT,
    audit_id INT NOT NULL,
    PRIMARY KEY(id, audit_id),
    FOREIGN KEY(audit_id) REFERENCES Audit_Info(audit_id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS `Additional_Student_Progress_Info` (
    student_id INT NOT NULL,
    email VARCHAR(255) NOT NULL,
    completion_term_code INT NOT NULL,
    graduation_ready BOOLEAN DEFAULT FALSE,
    missing_courses JSON,
    citizen_code VARCHAR(255) NOT NULL,
    transfer_flag BOOLEAN DEFAULT FALSE,
    cadet_flag BOOLEAN DEFAULT FALSE,
    student_class_desc VARCHAR(255) NOT NULL,
    self_reported_veteran_flag BOOLEAN DEFAULT FALSE,
    audit_id INT NOT NULL,
    PRIMARY KEY (student_id, audit_id),
    FOREIGN KEY (student_id, audit_id) REFERENCES Student_Progress(id, audit_id) ON DELETE CASCADE,
    FOREIGN KEY (audit_id) REFERENCES Audit_Info(audit_id) ON DELETE CASCADE 
);

CREATE TABLE IF NOT EXISTS `Progress_Course` (
    subj_expanded VARCHAR(8) NOT NULL,
    course_number VARCHAR(6) NOT NULL,
    term_taken INT NOT NULL,
    credit_hours INT NOT NULL,
    grade VARCHAR(4) NOT NULL,
    student_id INT NOT NULL,
    audit_id INT NOT NULL,
    PRIMARY KEY (student_id, audit_id, subj_expanded, course_number, term_taken),
    FOREIGN KEY (student_id, audit_id) REFERENCES Student_Progress(id, audit_id) ON DELETE CASCADE,
    FOREIGN KEY (audit_id) REFERENCES Audit_Info(audit_id) ON DELETE CASCADE 
);

-- P91

CREATE TABLE IF NOT EXISTS `Violation_Type` (
    id INT PRIMARY KEY NOT NULL,
    message VARCHAR(64) NOT NULL,
    warning_message VARCHAR(64)
);

CREATE TABLE IF NOT EXISTS `Student` (
    id INT PRIMARY KEY NOT NULL,
    name VARCHAR(128) NOT NULL,
    standing_message VARCHAR(64) NOT NULL,
    admit_term INT NOT NULL,
    current_term INT NOT NULL,
    concentration VARCHAR(3) DEFAULT "CS" NOT NULL,
    advisor_lname VARCHAR(64) NOT NULL,
    overall_hours_attempted INT NOT NULL,
    overall_gpa FLOAT NOT NULL,
    transfer_hours_earned INT NOT NULL,
    in_major_gpa FLOAT
);

CREATE TABLE IF NOT EXISTS `Additional_Student_Info` (
    student_id INT NOT NULL,
    email VARCHAR(255) NOT NULL UNIQUE,
    completion_term_code INT NOT NULL,
    graduation_ready BOOLEAN DEFAULT FALSE,
    missing_courses JSON,
    PRIMARY KEY (student_id, email),
    FOREIGN KEY (student_id) REFERENCES Student(id) ON DELETE CASCADE 
);

CREATE TABLE IF NOT EXISTS `Course` (
    subj_expanded VARCHAR(8) NOT NULL,
    course_number VARCHAR(6) NOT NULL,
    term_taken INT NOT NULL,
    credit_hours INT NOT NULL,
    grade VARCHAR(4) NOT NULL,
    student_id INT NOT NULL,
    FOREIGN KEY (student_id) REFERENCES Student(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS `Violation` (
    id INT PRIMARY KEY NOT NULL AUTO_INCREMENT,
    student_id INT NOT NULL,
    type INT NOT NULL,
    is_warning BOOLEAN NOT NULL,
    FOREIGN KEY (type) REFERENCES Violation_Type(id),
    FOREIGN KEY (student_id) REFERENCES Student(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS `Violation_Course` (
    violation_id INT NOT NULL,
    student_id INT NOT NULL,
    subj_expanded VARCHAR(8) NOT NULL,
    course_number VARCHAR(6) NOT NULL,
    term_taken INT NOT NULL,
    FOREIGN KEY (violation_id) REFERENCES Violation(id) ON DELETE CASCADE,
    FOREIGN KEY (student_id) REFERENCES Student(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS `Checksheet` (
    year INT NOT NULL,
    subject VARCHAR(4) NOT NULL,
    category VARCHAR(100) NOT NULL,
    course_number VARCHAR(6) NOT NULL,
    credit_hours INT NOT NULL,
    passing_grade VARCHAR(3) NOT NULL DEFAULT 'D-',
    repeatable BOOLEAN DEFAULT FALSE,
    conc_eligible VARCHAR(6) DEFAULT "cs",
    substitutes JSON,
    PRIMARY KEY (year, subject, course_number, category)
);

-- Force Add
CREATE TABLE IF NOT EXISTS`Instructor` (
    instructor_id varchar(100) NOT NULL,
    instructor_first varchar(100) NOT NULL,
    instructor_last varchar(100) NOT NULL
);

CREATE TABLE IF NOT EXISTS`Term` (
    termcode int(11) NOT NULL,
    open date DEFAULT NULL,
    close date DEFAULT NULL,
    PRIMARY KEY (termcode)
);

CREATE TABLE IF NOT EXISTS`Timetable` (
    termcode int(11) NOT NULL,
    crn int(11) NOT NULL,
    course_id varchar(9) NOT NULL,
    course_name varchar(100) NOT NULL,
    credit_hrs int(11) NOT NULL,
    instructor varchar(100) NOT NULL,
    meet_days varchar(7) DEFAULT NULL,
    begin_time int(11) NOT NULL,
    end_time int(11) NOT NULL,
    location varchar(100) NOT NULL,
    campus int(11) NOT NULL,
    current_enrollment int(11) NOT NULL,
    max_enrollment int(11) NOT NULL,
    active int(11) NOT NULL,
    PRIMARY KEY (termcode,crn),
    FOREIGN KEY (termcode) REFERENCES Term(termcode) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS`NewTimetable` (
    termcode int(11) NOT NULL,
    crn int(11) NOT NULL,
    course_id varchar(9) NOT NULL,
    course_name varchar(100) NOT NULL,
    credit_hrs int(11) NOT NULL,
    instructor varchar(100) NOT NULL,
    meet_days varchar(7) DEFAULT NULL,
    begin_time int(11) NOT NULL,
    end_time int(11) NOT NULL,
    location varchar(100) NOT NULL,
    campus int(11) NOT NULL,
    current_enrollment int(11) NOT NULL,
    max_enrollment int(11) NOT NULL,
    active int(11) NOT NULL,
    PRIMARY KEY (termcode,crn),
    FOREIGN KEY (termcode) REFERENCES Term(termcode) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS`ForceAdd` (
    forceadd_id int(11) NOT NULL AUTO_INCREMENT,
    pid varchar(16) NOT NULL,
    id_number int(11) NOT NULL,
    banner_name varchar(100) NOT NULL,
    banner_major varchar(100) NOT NULL,
    banner_campus varchar(100) NOT NULL,
    academic_level varchar(100) NOT NULL,
    degree varchar(100) NOT NULL,
    major varchar(100) NOT NULL,
    minor varchar(100) DEFAULT NULL,
    campus int(11) NOT NULL,
    grad_date int(11) NOT NULL,
    term int(11) NOT NULL,
    course_id varchar(9) NOT NULL,
    first_choice int(11) DEFAULT NULL,
    second_choice int(11) DEFAULT NULL,
    drops varchar(100) NOT NULL,
    reason int(11) NOT NULL,
    student_comment varchar(255) NOT NULL,
    submission_timestamp timestamp NOT NULL DEFAULT '1970-01-01 00:00:01',
    internal_comments varchar(255) NOT NULL,
    external_comments varchar(255) NOT NULL,
    status int(11) NOT NULL,
    status_timestamp timestamp NOT NULL DEFAULT current_timestamp(),
    emailed int(11) NOT NULL,
    PRIMARY KEY (forceadd_id),
    FOREIGN KEY (term) REFERENCES Term(termcode) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS`FAFiles` (
    fa_file_id INT(11) NOT NULL AUTO_INCREMENT,
    forceadd_id INT(11) NOT NULL,
    file_name VARCHAR(255) NOT NULL,
    PRIMARY KEY (fa_file_id),
    FOREIGN KEY (forceadd_id) REFERENCES ForceAdd(forceadd_id) ON DELETE CASCADE
);

-- Undergraduate Force Add
CREATE TABLE IF NOT EXISTS `UG_Term` (
    termcode int(11) NOT NULL,
    open date DEFAULT NULL,
    close date DEFAULT NULL,
    PRIMARY KEY (termcode)
);

CREATE TABLE IF NOT EXISTS `UG_Timetable` (
    termcode int(11) NOT NULL,
    crn int(11) NOT NULL,
    course_id varchar(9) NOT NULL,
    course_name varchar(100) NOT NULL,
    credit_hrs int(11) NOT NULL,
    instructor varchar(100) NOT NULL,
    meet_days varchar(7) DEFAULT NULL,
    begin_time int(11) NOT NULL,
    end_time int(11) NOT NULL,
    location varchar(100) NOT NULL,
    campus int(11) NOT NULL,
    current_enrollment int(11) NOT NULL,
    max_enrollment int(11) NOT NULL,
    active int(11) NOT NULL,
    ignore_enrollment INT NOT NULL,
    PRIMARY KEY (termcode,crn),
    FOREIGN KEY (termcode) REFERENCES UG_Term(termcode) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS `UG_ForceAdd` (
    forceadd_id int(11) NOT NULL AUTO_INCREMENT,
    pid varchar(16) NOT NULL,
    id_number int(11) NOT NULL,
    banner_name varchar(100) NOT NULL,
    banner_major varchar(100) NOT NULL,
    banner_campus varchar(100) NOT NULL,
    academic_level varchar(100) NOT NULL,
    degree varchar(100) NOT NULL,
    major varchar(100) NOT NULL,
    minor varchar(100) DEFAULT NULL,
    campus int(11) NOT NULL,
    grad_date int(11) NOT NULL,
    term int(11) NOT NULL,
    course_id varchar(9) NOT NULL,
    first_choice int(11) DEFAULT NULL,
    second_choice int(11) DEFAULT NULL,
    drops varchar(100) NOT NULL,
    reason int(11) NOT NULL,
    student_comment varchar(255) NOT NULL,
    submission_timestamp timestamp NOT NULL DEFAULT '1970-01-01 00:00:01',
    internal_comments varchar(255) NOT NULL,
    external_comments varchar(255) NOT NULL,
    status int(11) NOT NULL,
    status_timestamp timestamp NOT NULL DEFAULT current_timestamp(),
    emailed int(11) NOT NULL,
    PRIMARY KEY (forceadd_id),
    FOREIGN KEY (term) REFERENCES UG_Term(termcode) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS `UG_FAFiles` (
    fa_file_id INT(11) NOT NULL AUTO_INCREMENT,
    forceadd_id INT(11) NOT NULL,
    file_name VARCHAR(255) NOT NULL,
    PRIMARY KEY (fa_file_id),
    FOREIGN KEY (forceadd_id) REFERENCES UG_ForceAdd(forceadd_id) ON DELETE CASCADE
);

-- Graduate Force Add
CREATE TABLE IF NOT EXISTS `Grad_Term` (
    termcode int(11) NOT NULL,
    open date DEFAULT NULL,
    close date DEFAULT NULL,
    PRIMARY KEY (termcode)
);

CREATE TABLE IF NOT EXISTS `Grad_Timetable` (
    termcode int(11) NOT NULL,
    crn int(11) NOT NULL,
    course_id varchar(9) NOT NULL,
    course_name varchar(100) NOT NULL,
    credit_hrs int(11) NOT NULL,
    instructor varchar(100) NOT NULL,
    meet_days varchar(7) DEFAULT NULL,
    begin_time int(11) NOT NULL,
    end_time int(11) NOT NULL,
    location varchar(100) NOT NULL,
    campus int(11) NOT NULL,
    current_enrollment int(11) NOT NULL,
    max_enrollment int(11) NOT NULL,
    active int(11) NOT NULL,
    ignore_enrollment INT NOT NULL,
    PRIMARY KEY (termcode,crn),
    FOREIGN KEY (termcode) REFERENCES Grad_Term(termcode) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS `Grad_ForceAdd` (
    forceadd_id int(11) NOT NULL AUTO_INCREMENT,
    pid varchar(16) NOT NULL,
    id_number int(11) NOT NULL,
    banner_name varchar(100) NOT NULL,
    banner_major varchar(100) NOT NULL,
    banner_campus varchar(100) NOT NULL,
    academic_level varchar(100) NOT NULL,
    degree varchar(100) NOT NULL,
    major varchar(100) NOT NULL,
    minor varchar(100) DEFAULT NULL,
    campus int(11) NOT NULL,
    grad_date int(11) NOT NULL,
    term int(11) NOT NULL,
    course_id varchar(9) NOT NULL,
    first_choice int(11) DEFAULT NULL,
    second_choice int(11) DEFAULT NULL,
    drops varchar(100) NOT NULL,
    reason int(11) NOT NULL,
    student_comment varchar(255) NOT NULL,
    submission_timestamp timestamp NOT NULL DEFAULT '1970-01-01 00:00:01',
    internal_comments varchar(255) NOT NULL,
    external_comments varchar(255) NOT NULL,
    status int(11) NOT NULL,
    status_timestamp timestamp NOT NULL DEFAULT current_timestamp(),
    emailed int(11) NOT NULL,
    PRIMARY KEY (forceadd_id),
    FOREIGN KEY (term) REFERENCES Grad_Term(termcode) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS `Grad_FAFiles` (
    fa_file_id INT(11) NOT NULL AUTO_INCREMENT,
    forceadd_id INT(11) NOT NULL,
    file_name VARCHAR(255) NOT NULL,
    PRIMARY KEY (fa_file_id),
    FOREIGN KEY (forceadd_id) REFERENCES Grad_ForceAdd(forceadd_id) ON DELETE CASCADE
);

