-- Copy Pathways categories from 2025 into earlier years (2007–2024)

INSERT IGNORE INTO `Checksheet`
    (`year`,
     `subject`,
     `category`,
     `course_number`,
     `credit_hours`,
     `passing_grade`,
     `repeatable`,
     `conc_eligible`,
     `substitutes`)
SELECT
    y.year        AS year,
    c.subject     AS subject,
    c.category    AS category,
    c.course_number,
    c.credit_hours,
    c.passing_grade,
    c.repeatable,
    c.conc_eligible,
    c.substitutes
FROM `Checksheet` c
JOIN (
    SELECT 2007 AS year UNION ALL
    SELECT 2008 UNION ALL
    SELECT 2009 UNION ALL
    SELECT 2010 UNION ALL
    SELECT 2011 UNION ALL
    SELECT 2012 UNION ALL
    SELECT 2013 UNION ALL
    SELECT 2014 UNION ALL
    SELECT 2015 UNION ALL
    SELECT 2016 UNION ALL
    SELECT 2017 UNION ALL
    SELECT 2018 UNION ALL
    SELECT 2019 UNION ALL
    SELECT 2020 UNION ALL
    SELECT 2021 UNION ALL
    SELECT 2022 UNION ALL
    SELECT 2023 UNION ALL
    SELECT 2024
) AS y
  ON 1 = 1
WHERE c.year = 2025
  AND c.category IN ('1', '2', '3', '4', '5', '6', '6a');

-- Secure Computing concentration backfill

-- 1) Mark Secure concentration rows for 2025 correctly
UPDATE `Checksheet`
SET conc_eligible = 'Secure'
WHERE year = 2025
  AND category LIKE 'secure%';

-- 2) Clone the Secure Computing checksheet from 2025
--    back to all years 2007–2024.
INSERT IGNORE INTO `Checksheet`
    (`year`, `subject`, `category`, `course_number`,
     `credit_hours`, `passing_grade`, `repeatable`,
     `conc_eligible`, `substitutes`)
SELECT y.target_year,
       c.subject,
       c.category,
       c.course_number,
       c.credit_hours,
       c.passing_grade,
       c.repeatable,
       'Secure' AS conc_eligible,
       c.substitutes
FROM `Checksheet` c
JOIN (
    SELECT 2007 AS target_year UNION ALL
    SELECT 2008 UNION ALL
    SELECT 2009 UNION ALL
    SELECT 2010 UNION ALL
    SELECT 2011 UNION ALL
    SELECT 2012 UNION ALL
    SELECT 2013 UNION ALL
    SELECT 2014 UNION ALL
    SELECT 2015 UNION ALL
    SELECT 2016 UNION ALL
    SELECT 2017 UNION ALL
    SELECT 2018 UNION ALL
    SELECT 2019 UNION ALL
    SELECT 2020 UNION ALL
    SELECT 2021 UNION ALL
    SELECT 2022 UNION ALL
    SELECT 2023 UNION ALL
    SELECT 2024
) AS y
  ON c.year = 2025
 AND c.category LIKE 'secure%';

-- Add the stuff for the User id default b/c MariaDB does not have UUID_TO_BIN and doesn't support stored functions as default

-- Data-Centric Computing concentration backfill

-- 1) Mark Data concentration rows for 2025 correctly
UPDATE `Checksheet`
SET conc_eligible = 'DCC'
WHERE year = 2025
  AND category LIKE 'data-centric%';

-- 2) Clone the Data-Centric Computing checksheet from 2025
--    back to all years 2007–2024.
INSERT IGNORE INTO `Checksheet`
    (`year`, `subject`, `category`, `course_number`,
     `credit_hours`, `passing_grade`, `repeatable`,
     `conc_eligible`, `substitutes`)
SELECT y.target_year,
       c.subject,
       c.category,
       c.course_number,
       c.credit_hours,
       c.passing_grade,
       c.repeatable,
       'DCC' AS conc_eligible,
       c.substitutes
FROM `Checksheet` c
JOIN (
    SELECT 2007 AS target_year UNION ALL
    SELECT 2008 UNION ALL
    SELECT 2009 UNION ALL
    SELECT 2010 UNION ALL
    SELECT 2011 UNION ALL
    SELECT 2012 UNION ALL
    SELECT 2013 UNION ALL
    SELECT 2014 UNION ALL
    SELECT 2015 UNION ALL
    SELECT 2016 UNION ALL
    SELECT 2017 UNION ALL
    SELECT 2018 UNION ALL
    SELECT 2019 UNION ALL
    SELECT 2020 UNION ALL
    SELECT 2021 UNION ALL
    SELECT 2022 UNION ALL
    SELECT 2023 UNION ALL
    SELECT 2024
) AS y
  ON c.year = 2025
 AND c.category LIKE 'data-centric%';

