       c.subject,
       c.category,
       c.course_number,
       c.credit_hours,
       c.passing_grade,
       c.repeatable,
       'CS' AS conc_eligible,
       c.substitutes
FROM `Checksheet` c
JOIN (
    SELECT 2007 AS target_year UNION ALL
    SELECT 2008 UNION ALL
    SELECT 2009 UNION ALL
    SELECT 2010 UNION ALL
    SELECT 2011 UNION ALL
    SELECT 2012 UNION ALL
    SELECT 2013 UNION ALL
    SELECT 2014 UNION ALL
    SELECT 2015 UNION ALL
    SELECT 2016 UNION ALL
    SELECT 2017 UNION ALL
    SELECT 2018 UNION ALL
    SELECT 2019 UNION ALL
    SELECT 2020 UNION ALL
    SELECT 2021 UNION ALL
    SELECT 2022 UNION ALL
    SELECT 2023 UNION ALL
    SELECT 2024
) AS y
  ON c.year = 2025
 AND c.category LIKE '3xxx%';

-- Add the stuff for the User id default b/c MariaDB does not have UUID_TO_BIN and doesn't support stored functions as default

-- 45xxx  backfill

-- 1) Mark 45xxx rows for 2025 correctly
UPDATE `Checksheet`
SET conc_eligible = 'CS'
WHERE year = 2025
  AND category LIKE '45xxx%';

-- 2) Clone the 45xxx checksheet from 2025
--    back to all years 2007–2024.
INSERT IGNORE INTO `Checksheet`
    (`year`, `subject`, `category`, `course_number`,
     `credit_hours`, `passing_grade`, `repeatable`,
     `conc_eligible`, `substitutes`)
SELECT y.target_year,
       c.subject,
       c.category,
       c.course_number,
       c.credit_hours,
       c.passing_grade,
       c.repeatable,
       'CS' AS conc_eligible,
       c.substitutes
FROM `Checksheet` c
JOIN (
    SELECT 2007 AS target_year UNION ALL
    SELECT 2008 UNION ALL
    SELECT 2009 UNION ALL
    SELECT 2010 UNION ALL
    SELECT 2011 UNION ALL
    SELECT 2012 UNION ALL
    SELECT 2013 UNION ALL
    SELECT 2014 UNION ALL
    SELECT 2015 UNION ALL
    SELECT 2016 UNION ALL
    SELECT 2017 UNION ALL
    SELECT 2018 UNION ALL
    SELECT 2019 UNION ALL
    SELECT 2020 UNION ALL
    SELECT 2021 UNION ALL
    SELECT 2022 UNION ALL
    SELECT 2023 UNION ALL
    SELECT 2024
) AS y
  ON c.year = 2025
 AND c.category LIKE '45xxx%';

-- Add the stuff for the User id default b/c MariaDB does not have UUID_TO_BIN and doesn't support stored functions as default


