DROP PROCEDURE IF EXISTS `UpdateTimeTable`;;
CREATE PROCEDURE `UpdateTimeTable` ()
BEGIN
    -- Update Instructors --
    UPDATE NewTimetable t
    INNER JOIN Instructor i ON t.instructor = i.instructor_id
    SET t.instructor = CONCAT(i.instructor_last,", ",i.instructor_first);

    -- Update details of existing sections
    UPDATE UG_Timetable
    INNER JOIN NewTimetable ON NewTimetable.crn = UG_Timetable.crn AND NewTimetable.termcode = UG_Timetable.termcode
    SET
        UG_Timetable.course_id = NewTimetable.course_id,
        UG_Timetable.course_name = NewTimetable.course_name,
        UG_Timetable.credit_hrs = NewTimetable.credit_hrs,
        UG_Timetable.instructor = NewTimetable.instructor,
        UG_Timetable.meet_days = NewTimetable.meet_days,
        UG_Timetable.begin_time = NewTimetable.begin_time,
        UG_Timetable.end_time = NewTimetable.end_time,
        UG_Timetable.location = NewTimetable.location,
        UG_Timetable.campus = NewTimetable.campus,
        UG_Timetable.current_enrollment = NewTimetable.current_enrollment,
        UG_Timetable.max_enrollment = NewTimetable.max_enrollment
    WHERE NewTimetable.crn = UG_Timetable.crn AND NewTimetable.termcode = UG_Timetable.termcode;

    UPDATE Grad_Timetable
    INNER JOIN NewTimetable ON NewTimetable.crn = Grad_Timetable.crn AND NewTimetable.termcode = Grad_Timetable.termcode
    SET
        Grad_Timetable.course_id = NewTimetable.course_id,
        Grad_Timetable.course_name = NewTimetable.course_name,
        Grad_Timetable.credit_hrs = NewTimetable.credit_hrs,
        Grad_Timetable.instructor = NewTimetable.instructor,
        Grad_Timetable.meet_days = NewTimetable.meet_days,
        Grad_Timetable.begin_time = NewTimetable.begin_time,
        Grad_Timetable.end_time = NewTimetable.end_time,
        Grad_Timetable.location = NewTimetable.location,
        Grad_Timetable.campus = NewTimetable.campus,
        Grad_Timetable.current_enrollment = NewTimetable.current_enrollment,
        Grad_Timetable.max_enrollment = NewTimetable.max_enrollment
    WHERE NewTimetable.crn = Grad_Timetable.crn AND NewTimetable.termcode = Grad_Timetable.termcode;

    -- Insert the new timetable entries
    INSERT INTO UG_Timetable
    SELECT 
        NewTimetable.termcode,
        NewTimetable.crn,
        NewTimetable.course_id,
        NewTimetable.course_name,
        NewTimetable.credit_hrs,
        NewTimetable.instructor,
        NewTimetable.meet_days,
        NewTimetable.begin_time,
        NewTimetable.end_time,
        NewTimetable.location,
        NewTimetable.campus,
        NewTimetable.current_enrollment,
        NewTimetable.max_enrollment,
        IF(TT.active IS NOT NULL, TT.active, 0),
        IF(TT.ignore_enrollment IS NOT NULL, TT.ignore_enrollment, 0)
    FROM NewTimetable
    LEFT JOIN UG_Timetable AS UG_Timetable ON NewTimetable.crn = UG_Timetable.crn AND NewTimetable.termcode = UG_Timetable.termcode
    LEFT JOIN UG_Timetable AS TT ON NewTimetable.crn = TT.crn AND NewTimetable.termcode-100 = TT.termcode
    WHERE
        UG_Timetable.crn IS NULL AND
        UG_Timetable.termcode IS NULL AND
        (
            NewTimetable.course_id LIKE 'CS 1%' OR
            NewTimetable.course_id LIKE 'CS 2%' OR
            NewTimetable.course_id LIKE 'CS 3%' OR
            NewTimetable.course_id LIKE 'CS 4%'
        )
    ;


    INSERT INTO Grad_Timetable
    SELECT 
        NewTimetable.termcode,
        NewTimetable.crn,
        NewTimetable.course_id,
        NewTimetable.course_name,
        NewTimetable.credit_hrs,
        NewTimetable.instructor,
        NewTimetable.meet_days,
        NewTimetable.begin_time,
        NewTimetable.end_time,
        NewTimetable.location,
        NewTimetable.campus,
        NewTimetable.current_enrollment,
        NewTimetable.max_enrollment,
        IF(TT.active IS NOT NULL, TT.active, 0),
        IF(TT.ignore_enrollment IS NOT NULL, TT.ignore_enrollment, 0)
    FROM NewTimetable
    LEFT JOIN Grad_Timetable AS Grad_Timetable ON NewTimetable.crn = Grad_Timetable.crn AND NewTimetable.termcode = Grad_Timetable.termcode
    LEFT JOIN Grad_Timetable AS TT ON NewTimetable.crn = TT.crn AND NewTimetable.termcode-100 = TT.termcode
    WHERE
        Grad_Timetable.crn IS NULL AND
        Grad_Timetable.termcode IS NULL AND
        (
            NewTimetable.course_id LIKE 'CS 5%' OR
            NewTimetable.course_id LIKE 'CS 6%' OR
            NewTimetable.course_id LIKE 'CS 7%' OR
            NewTimetable.course_id LIKE 'CS 8%'
        )
    ;

    -- Clear Out NewTimetable
    TRUNCATE TABLE NewTimetable;
END;;

DROP TRIGGER IF EXISTS `AddNewTerms_bi`;;
CREATE TRIGGER `AddNewTerms_bi` BEFORE INSERT ON `NewTimetable` FOR EACH ROW
BEGIN
    INSERT IGNORE INTO Term
    VALUES(NEW.termcode, NULL,NULL);

    INSERT IGNORE INTO UG_Term
    VALUES(NEW.termcode, NULL,NULL);
    
    INSERT IGNORE INTO Grad_Term
    VALUES(NEW.termcode, NULL,NULL);
END;;

DELIMITER ;
